void insertBefore(Bucket bucket){
    if (bucket == null) {
        throw new IllegalArgumentException("Bucket cannot be null");
    }
    if (bucket == this) {
        throw new IllegalArgumentException("Cannot insert a bucket before itself");
    }

    // If the bucket to insert before is the head, this becomes the new head
    if (bucket == head) {
        this.next = bucket;
        this.prev = null;
        bucket.prev = this;
        head = this;
    } else {
        // Find the previous bucket of the target bucket
        Bucket prev = bucket.prev;
        if (prev == null) {
            // This should not happen if bucket is not head, but handle defensively
            throw new IllegalStateException("Bucket has no previous bucket");
        }

        // Insert this bucket between prev and bucket
        this.next = bucket;
        this.prev = prev;
        prev.next = this;
        bucket.prev = this;
    }
}

