protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    if (sourceVertex == null || targetVertex == null || e == null) {
        throw new IllegalArgumentException("Source vertex, target vertex, and edge must not be null");
    }

    // Add the edge to the adjacency list of the source vertex
    if (!adjacency.containsKey(sourceVertex)) {
        adjacency.put(sourceVertex, new ArrayList<>());
    }
    adjacency.get(sourceVertex).add(e);

    // If the graph is undirected, also add the edge to the adjacency list of the target vertex
    if (!isDirected) {
        if (!adjacency.containsKey(targetVertex)) {
            adjacency.put(targetVertex, new ArrayList<>());
        }
        adjacency.get(targetVertex).add(e);
    }
}

