private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes must not be null");
    }

    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    Node current = start;

    // If start is the stop node, check if it satisfies the predicate
    if (current == stop) {
        if (predicate.test(current)) {
            return circulator;
        }
        // If stop doesn't satisfy predicate, we need to traverse the entire outer face
        // and return to stop
    }

    // Traverse the outer face
    do {
        circulator.advance();
        current = circulator.node();

        if (predicate.test(current)) {
            return circulator;
        }

        // Check if we've reached the stop node
        if (current == stop) {
            return circulator;
        }
    } while (current != start);

    // If we've completed a full cycle without finding a node satisfying the predicate
    // and without reaching stop (which shouldn't happen if stop is on the outer face),
    // return the circulator at the stop node
    // This case should be handled by the loop above, but as a safety measure:
    return new OuterFaceCirculator(stop, dir);
}

