protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, new ArrayList<>(), new ArrayList<>());
    }

    // Build adjacency list from the tour edges
    Map<V, List<V>> adjacency = new HashMap<>();
    Map<V, List<E>> edgeMap = new HashMap<>();

    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        adjacency.computeIfAbsent(source, k -> new ArrayList<>()).add(target);
        adjacency.computeIfAbsent(target, k -> new ArrayList<>()).add(source);

        edgeMap.computeIfAbsent(source, k -> new ArrayList<>()).add(edge);
        edgeMap.computeIfAbsent(target, k -> new ArrayList<>()).add(edge);
    }

    // Find a starting vertex (one with degree 1, or any vertex if all have degree 2)
    V start = null;
    for (V vertex : adjacency.keySet()) {
        if (adjacency.get(vertex).size() == 1) {
            start = vertex;
            break;
        }
    }
    if (start == null) {
        // All vertices have degree 2, pick any
        start = adjacency.keySet().iterator().next();
    }

    // Build the path by following edges
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();

    V current = start;
    V previous = null;
    vertices.add(current);

    Set<E> usedEdges = new HashSet<>();

    while (true) {
        List<V> neighbors = adjacency.get(current);
        if (neighbors == null || neighbors.isEmpty()) {
            break;
        }

        V next = null;
        E nextEdge = null;

        for (V neighbor : neighbors) {
            if (neighbor.equals(previous)) {
                continue;
            }
            // Find the edge between current and neighbor
            List<E> edgesFromCurrent = edgeMap.get(current);
            if (edgesFromCurrent != null) {
                for (E e : edgesFromCurrent) {
                    if (usedEdges.contains(e)) {
                        continue;
                    }
                    V src = graph.getEdgeSource(e);
                    V tgt = graph.getEdgeTarget(e);
                    if ((src.equals(current) && tgt.equals(neighbor)) || 
                        (tgt.equals(current) && src.equals(neighbor))) {
                        next = neighbor;
                        nextEdge = e;
                        break;
                    }
                }
            }
            if (next != null) {
                break;
            }
        }

        if (next == null) {
            break;
        }

        usedEdges.add(nextEdge);
        edges.add(nextEdge);
        vertices.add(next);

        previous = current;
        current = next;
    }

    return new GraphPathImpl<>(graph, vertices, edges);
}

