private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
    List<Pair<List<Pair<Integer,Integer>>,E>> result = new ArrayList<>();
    if (graph == null) {
        return result;
    }
    for (E edge : graph.edges()) {
        int u = graph.getEdgeSource(edge);
        int v = graph.getEdgeTarget(edge);
        // Compute the neighborhood of the edge (u, v)
        // The neighborhood of an edge (u, v) is the set of vertices adjacent to both u and v, excluding u and v themselves
        Set<Integer> neighborsU = new HashSet<>();
        Set<Integer> neighborsV = new HashSet<>();
        for (int w : graph.getNeighbors(u)) {
            if (w != v) {
                neighborsU.add(w);
            }
        }
        for (int w : graph.getNeighbors(v)) {
            if (w != u) {
                neighborsV.add(w);
            }
        }
        // The neighborhood of the edge is the intersection of neighborsU and neighborsV
        Set<Integer> neighborhood = new HashSet<>(neighborsU);
        neighborhood.retainAll(neighborsV);

        // Find all minimal separators in the neighborhood
        // A minimal separator is a minimal set of vertices whose removal disconnects u and v
        // We need to find all minimal vertex cuts between u and v in the graph induced by the neighborhood plus u and v
        // This is a complex problem. For simplicity, we'll use a heuristic or a known algorithm.
        // However, since this is a private method and the exact algorithm is not specified, 
        // we'll implement a basic approach: find all minimal separators by checking all subsets of the neighborhood.
        // This is exponential in the worst case, but for small graphs it's feasible.

        List<List<Pair<Integer,Integer>>> separators = new ArrayList<>();
        List<Integer> neighborhoodList = new ArrayList<>(neighborhood);
        int n = neighborhoodList.size();

        // If the neighborhood is empty, there are no separators
        if (n == 0) {
            continue;
        }

        // Generate all subsets of the neighborhood
        for (int mask = 1; mask < (1 << n); mask++) {
            List<Integer> separator = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    separator.add(neighborhoodList.get(i));
                }
            }

            // Check if this separator is a valid separator (removing it disconnects u and v)
            if (isSeparator(u, v, separator)) {
                // Check if it's minimal
                boolean isMinimal = true;
                for (int i = 0; i < separator.size(); i++) {
                    List<Integer> smallerSeparator = new ArrayList<>(separator);
                    smallerSeparator.remove(i);
                    if (isSeparator(u, v, smallerSeparator)) {
                        isMinimal = false;
                        break;
                    }
                }
                if (isMinimal) {
                    // Convert to List<Pair<Integer,Integer>>
                    List<Pair<Integer,Integer>> separatorPairs = new ArrayList<>();
                    for (int vertex : separator) {
                        separatorPairs.add(new Pair<>(vertex, vertex));
                    }
                    separators.add(separatorPairs);
                }
            }
        }

        // Add all separators for this edge to the result
        for (List<Pair<Integer,Integer>> separator : separators) {
            result.add(new Pair<>(separator, edge));
        }
    }
    return result;
}

