public Action inspect(AtmosphereResource r) {
    if (r == null) {
        return Action.CONTINUE;
    }

    try {
        Transport transport = r.transport();
        if (transport != null) {
            switch (transport) {
                case WEBSOCKET:
                case WEBSOCKET_FALLBACK:
                    // For WebSocket transports, no suspension needed
                    break;
                case COMET:
                case LONG_POLLING:
                case SSE:
                    // Suspend the resource for these transports
                    r.suspend();
                    break;
                default:
                    // For other transports, do nothing
                    break;
            }
        }
    } catch (Exception e) {
        // Log the exception or handle it appropriately
    }

    return Action.CONTINUE;
}

