public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path must not be null");
    }

    // Normalize the base path: ensure it ends with a separator if it's a directory
    // But we need to handle the case where path might be a file path
    // The relative path is applied relative to the directory containing 'path'

    // Get the directory part of the path
    String directory;
    int lastSlash = path.lastIndexOf('/');
    if (lastSlash == -1) {
        // No slash in path, so the directory is the current directory (represented as empty or ".")
        directory = "";
    } else {
        directory = path.substring(0, lastSlash + 1);
    }

    // Combine directory with relative path
    String combined = directory + relativePath;

    // Normalize the combined path: resolve "." and ".." segments
    String[] parts = combined.split("/");
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();

    for (String part : parts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pop();
            }
            // If stack is empty, we can't go above root, so ignore
        } else {
            stack.push(part);
        }
    }

    // Reconstruct the path
    StringBuilder result = new StringBuilder();
    // Check if the original path started with a slash (absolute path)
    boolean isAbsolute = path.startsWith("/");
    if (isAbsolute) {
        result.append("/");
    }

    // The stack is in reverse order, so we need to reverse it
    java.util.List<String> reversed = new java.util.ArrayList<>();
    while (!stack.isEmpty()) {
        reversed.add(stack.pop());
    }

    for (int i = 0; i < reversed.size(); i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(reversed.get(i));
    }

    // If the result is empty and it's an absolute path, return "/"
    if (result.length() == 0) {
        return isAbsolute ? "/" : "";
    }

    return result.toString();
}

