public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (nameStart < 0 || nameStart >= name.length()) {
        return;
    }
    // Find the end of the name
    int nameEnd = nameStart;
    while (nameEnd < name.length() && name.charAt(nameEnd) != ' ') {
        nameEnd++;
    }
    // If the name is a single character, just append it
    if (nameEnd - nameStart == 1) {
        buf.append(name.charAt(nameStart));
    } else {
        // Append the first character and the last character of the name
        buf.append(name.charAt(nameStart));
        buf.append(name.charAt(nameEnd - 1));
    }
}

