    List<SequenceRange> sequenceRanges = new ArrayList<>();
    if (currentProfiles == null || currentProfiles.isEmpty()) {
        return sequenceRanges;
    }

    // Group profiles by their segment
    Map<String, List<Profile>> profilesBySegment = new HashMap<>();
    for (Profile profile : currentProfiles) {
        if (profile.getSegment() != null) {
            profilesBySegment.computeIfAbsent(profile.getSegment(), k -> new ArrayList<>()).add(profile);
        }
    }

    // For each segment, build sequence ranges
    for (Map.Entry<String, List<Profile>> entry : profilesBySegment.entrySet()) {
        String segment = entry.getKey();
        List<Profile> profiles = entry.getValue();

        // Sort profiles by sequence number
        profiles.sort(Comparator.comparing(Profile::getSequenceNumber));

        // Build contiguous ranges
        int start = profiles.get(0).getSequenceNumber();
        int end = start;

        for (int i = 1; i < profiles.size(); i++) {
            int currentSeq = profiles.get(i).getSequenceNumber();
            if (currentSeq == end + 1) {
                end = currentSeq;
            } else {
                sequenceRanges.add(new SequenceRange(segment, start, end));
                start = currentSeq;
                end = currentSeq;
            }
        }

        // Add the last range
        sequenceRanges.add(new SequenceRange(segment, start, end));
    }

    return sequenceRanges;
}

