public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    if (file == null || !file.exists() || !file.isFile()) {
        return result;
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        return result;
    }

    // Determine the overall time range from the provided time ranges
    long minTime = Long.MAX_VALUE;
    long maxTime = Long.MIN_VALUE;
    for (ProfileAnalyzeTimeRange range : timeRanges) {
        if (range == null) {
            continue;
        }
        long start = range.getStartTime();
        long end = range.getEndTime();
        if (start < minTime) {
            minTime = start;
        }
        if (end > maxTime) {
            maxTime = end;
        }
    }

    if (minTime > maxTime) {
        return result;
    }

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            try {
                ThreadSnapshot snapshot = parseThreadSnapshot(line);
                if (snapshot != null) {
                    long timestamp = snapshot.getTimestamp();
                    if (isInTimeRange(timestamp, timeRanges)) {
                        result.add(snapshot);
                    }
                }
            } catch (Exception e) {
                // Skip lines that cannot be parsed
            }
        }
    }

    return result;
}

