private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor must not be null");
    }

    int i = 0;
    int len = descriptor.length();

    // If it's a method descriptor, skip the opening parenthesis
    if (len > 0 && descriptor.charAt(0) == '(') {
        i = 1;
        // Find the closing parenthesis
        int closeParen = descriptor.indexOf(')', i);
        if (closeParen == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing closing parenthesis");
        }
        i = closeParen + 1;
    }

    // Now pop types from the descriptor
    while (i < len) {
        char c = descriptor.charAt(i);
        switch (c) {
            case 'B': // boolean
            case 'C': // char
            case 'D': // double
            case 'F': // float
            case 'I': // int
            case 'J': // long
            case 'S': // short
            case 'Z': // boolean
                outputFrame.pop();
                i++;
                break;
            case 'L': // object type
                int semi = descriptor.indexOf(';', i);
                if (semi == -1) {
                    throw new IllegalArgumentException("Invalid type descriptor: missing semicolon");
                }
                outputFrame.pop();
                i = semi + 1;
                break;
            case '[': // array
                outputFrame.pop();
                i++;
                break;
            case ')': // end of method arguments
                // If we're in a method descriptor, we should stop here
                return;
            default:
                throw new IllegalArgumentException("Invalid descriptor character: " + c);
        }
    }
}

