public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("out is null");
    }
    if (message == null) {
        throw new NullPointerException("message is null");
    }
    if (schema == null) {
        throw new NullPointerException("schema is null");
    }
    if (buffer == null) {
        throw new NullPointerException("buffer is null");
    }

    int size = schema.getSerializedSize(message, buffer);
    if (size < 0) {
        throw new IllegalArgumentException("Invalid serialized size: " + size);
    }

    // Write the size as a varint
    CodedOutputStream cOut = CodedOutputStream.newInstance(out);
    cOut.writeUInt32NoTag(size);
    cOut.flush();

    // Write the message
    schema.writeTo(message, out, buffer);

    return size;
}

