public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("String must not be null");
    }
    if (index < 0 || index > str.length()) {
        throw new IndexOutOfBoundsException("Index out of bounds: " + index);
    }
    if (len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Length out of bounds: " + len);
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            size += 1;
        } else if (c < 0x800) {
            size += 2;
        } else if (c < 0xD800 || c > 0xDFFF) {
            size += 3;
        } else {
            // Surrogate pair
            if (i + 1 < str.length() && Character.isHighSurrogate(c) && Character.isLowSurrogate(str.charAt(i + 1))) {
                size += 4;
                i++; // Skip the low surrogate
            } else {
                // Invalid surrogate, treat as 3 bytes (or throw, but let's be lenient)
                size += 3;
            }
        }
    }
    return size;
}

