public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("DataOutput must not be null");
    }
    if (node == null) {
        throw new IllegalArgumentException("LinkedBuffer must not be null");
    }

    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        byte[] data = current.getData();
        if (data != null) {
            out.write(data);
            totalSize += data.length;
        }
        current = current.getNext();
    }
    return totalSize;
}

